//! The origin's real output on the committed synthetic fixture day
//! (`fixtures/synthetic/hl/base`, generated by `tools/hl-synth`; synthetic,
//! no admission needed) validates against the published JSON Schema,
//! `docs/specs/observation-v0.schema.json`.
//!
//! The node files go through the node reader's line filter and the
//! archive parser (`origin::hooks::NodeParser`: the same reader, joiner
//! and deriver as the live origin), so the records are trades, book events,
//! book snapshots, bars, analytics and coverage exactly as published.
//! Parquet output is checked against the Arrow schema document by the
//! archive's own tests.

#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::collections::BTreeMap;
use std::path::PathBuf;

use archive::layout::Day;
use archive::replay::RawFile;
use hl_node_reader::Stream;
use mesh_types::{RecordKind, Registry};
use origin::derive::{BookStart, DeriveConfig};
use origin::hooks::{NodeParser, line_filter};
use serde_json::Value;

const SCHEMA_URL: &str = "https://bleh.xyz/specs/observation-v0.schema.json";

fn repo() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// The base scenario's filtered raw files, sorted by (hour, stream) as
/// the archive passes them.
fn raw_files() -> Vec<RawFile> {
    let base = repo().join("fixtures/synthetic/hl/base");
    let day = Day::from_millis(1_767_225_600_000); // 2026-01-01
    let mut out = Vec::new();
    for hour in [0_u8, 1] {
        for stream in Stream::ALL {
            let rel = format!("node_{}_by_block/hourly/20260101/{hour}", stream.as_str());
            let text = std::fs::read_to_string(base.join(&rel)).unwrap();
            let filter = line_filter(stream);
            let mut data = Vec::new();
            for line in text.lines() {
                if let Some(kept) = filter.filter_line(line.as_bytes()) {
                    data.extend_from_slice(&kept);
                    data.push(b'\n');
                }
            }
            out.push(RawFile {
                stream: stream.as_str().to_owned(),
                day,
                hour,
                path: rel,
                data,
            });
        }
    }
    out
}

#[test]
fn origin_output_validates_against_json_schema() {
    let registry: Registry = serde_json::from_str(
        &std::fs::read_to_string(repo().join("fixtures/synthetic/hl/markets.json")).unwrap(),
    )
    .unwrap();
    let mut derive = DeriveConfig::hyperliquid().unwrap();
    derive.book_start = BookStart::Empty;
    let records = NodeParser::new(registry, derive)
        .parse_files(&raw_files())
        .unwrap();

    let schema: Value = serde_json::from_str(
        &std::fs::read_to_string(repo().join("docs/specs/observation-v0.schema.json")).unwrap(),
    )
    .unwrap();
    let mut schemas = boon::Schemas::new();
    let mut compiler = boon::Compiler::new();
    compiler.add_resource(SCHEMA_URL, schema).unwrap();
    let index = compiler.compile(SCHEMA_URL, &mut schemas).unwrap();

    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    for r in &records {
        let v = serde_json::to_value(r).unwrap();
        if let Err(e) = schemas.validate(&v, index) {
            panic!("{}: {e:#}\n{v}", r.kind());
        }
        *counts.entry(r.kind().as_str()).or_default() += 1;
    }
    // The fixture day exercises the reader, the book builder and coverage.
    for kind in [
        RecordKind::Trade,
        RecordKind::BookEvent,
        RecordKind::Bar,
        RecordKind::Coverage,
    ] {
        assert!(
            counts.contains_key(kind.as_str()),
            "no {kind} records: {counts:?}"
        );
    }
    eprintln!("validated {} records: {counts:?}", records.len());
}
